import { useState } from "react";
import useHttp from "./use_http";
import { useFormik } from "formik";
import toast from "react-hot-toast";
import { useDispatch } from "react-redux";
import { useNavigate } from "react-router-dom";
import formatHelper from "../helper/format_helper";
import { setDeleteModal } from "../redux/subscriber_slice";
import { message } from "antd";
import {
  DIRECTION_DATA,
  IP_DATA,
  OPERATOR_DETERMINED_BARRING,
  PRIORITY_LEVEL_DATA,
  QI_QCI_DATA,
  STATUS_DATA,
  SUBSCRIBER_STATUS,
  UNITS,
  USIM_TYPES,
} from "../utility/Utils";

const useSubscribers = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { httpService } = useHttp();

  const [loadings, setLoadings] = useState({
    getSubscribers: false,
    getSubscriberById: false,
    createSubscriber: false,
    updateSubscriber: false,
    deleteSubscriber: false,
  });

  const [paginates, setPaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    imsi: "",
    msisdn: "",
    ue_ipv4_address: "",
    ue_ipv6_address: "",
    smf_ipv4_address: "",
    smf_ipv6_address: "",
  });

  const [viewSubscriberData, setViewSubscriberData] = useState(null);

  const [openSearchbar, setOpenSearchbar] = useState("1");
  const [validations, setValidations] = useState({
    imsi: "",
    msisdn_1: "",
    msisdn_2: "",
    subscriber_key: "",
    amf: "",
    operator_key: "",
    ue_ambr_downlink: "",
    ue_ambr_uplink: "",
  });
  const [showValidations, setShowValidations] = useState(true);
  const [subscribersData, setSubscribersData] = useState([]);

  const getSubscribers = async (page, without_filters) => {
    let paramsData = {
      page: page,
      per_page: paginates.per_page,
    };
    // imsi
    if (!without_filters && filters.imsi.length > 0) {
      paramsData["imsi"] = formatHelper.toEnglishString(filters.imsi);
    }
    // msisdn
    if (!without_filters && filters.msisdn.length > 0) {
      paramsData["msisdn"] = formatHelper.toEnglishString(filters.msisdn);
    }
    // ue_ipv4_address
    if (!without_filters && filters.ue_ipv4_address.length > 0) {
      paramsData["ue_ipv4_address"] = formatHelper.toEnglishString(
        filters.ue_ipv4_address
      );
    }
    // ue_ipv6_address
    if (!without_filters && filters.ue_ipv6_address.length > 0) {
      paramsData["ue_ipv6_address"] = formatHelper.toEnglishString(
        filters.ue_ipv6_address
      );
    }
    // smf_ipv4_address
    if (!without_filters && filters.smf_ipv4_address.length > 0) {
      paramsData["smf_ipv4_address"] = formatHelper.toEnglishString(
        filters.smf_ipv4_address
      );
    }
    // smf_ipv6_address
    if (!without_filters && filters.smf_ipv6_address.length > 0) {
      paramsData["smf_ipv6_address"] = formatHelper.toEnglishString(
        filters.smf_ipv6_address
      );
    }
    try {
      setLoadings({ ...loadings, getSubscribers: true });
      setOpenSearchbar(undefined);
      const response = await httpService.get(`/v1/subscribers`, {
        params: paramsData,
      });
      setLoadings({ ...loadings, getSubscribers: false });
      if (response.data.data) {
        setSubscribersData(response.data.data);
        if (response.data.total > paginates.per_page) {
          setPaginates({
            ...paginates,
            total: Math.ceil(response.data.total / paginates.per_page),
            current: page,
          });
        } else {
          setPaginates({ ...paginates, total: 1, current: page });
        }
      } else {
        setSubscribersData([]);
        setPaginates({ ...paginates, total: 1, current: page });
      }
    } catch ({ err, response }) {
      setLoadings({ ...loadings, getSubscribers: false });
    }
  };

  const getSubscriberById = async (imsi) => {
    let paramsData = {
      page: 1,
      per_page: 10,
      imsi: imsi,
    };
    try {
      setLoadings({ ...loadings, getSubscriberById: true });
      const response = await httpService.get(`/v1/subscribers`, {
        params: paramsData,
      });
      setLoadings({ ...loadings, getSubscriberById: false });
      if (response.data.data) {
        let res = response.data.data[0];
        let newObject = {
          imsi: res.imsi ? res.imsi : "",
          msisdn: res.msisdn ? res.msisdn : [],
          subscriber_key: res?.security?.k ? res.security.k : "",
          amf: res?.security?.amf ? res.security.amf : "",
          usim_type: USIM_TYPES.find((o) => o.value == res.security.op_type),
          operator_key: res?.security?.op_value ? res.security.op_value : "",
          ue_ambr_downlink: res.ambr.downlink.value,
          ue_ambr_downlink_unit: UNITS.find(
            (o) => o.value == res.ambr.downlink.unit
          ),
          ue_ambr_uplink: res.ambr.uplink.value,
          ue_ambr_uplink_unit: UNITS.find(
            (o) => o.value == res.ambr.uplink.unit
          ),
          subscriber_status: SUBSCRIBER_STATUS.find(
            (o) => o.value == res.subscriber_status
          ),
          operator_determined_barring: OPERATOR_DETERMINED_BARRING.find(
            (o) => o.value == 0
          ),
          slice: res.slice.map((sliceItem) => ({
            sst: sliceItem.sst,
            sd: sliceItem.sd ? sliceItem.sd : "",
            default_indicator: sliceItem.default_indicator,
            session: sliceItem.session?.map((sessionItem) => ({
              dnn_apn: sessionItem.name,
              type: IP_DATA.find((o) => o.value == sessionItem.type),
              qi_qci: QI_QCI_DATA.find((o) => o.value == sessionItem.qos.index),
              arp_priority_level: PRIORITY_LEVEL_DATA.find(
                (o) => o.value == sessionItem.qos.arp.priority_level
              ),
              capability: STATUS_DATA.find(
                (o) => o.value == sessionItem.qos.arp.pre_emption_capability
              ),
              vulnerability: STATUS_DATA.find(
                (o) => o.value == sessionItem.qos.arp.pre_emption_vulnerability
              ),
              session_ambr_downlink: sessionItem.ambr.downlink.value,
              session_ambr_downlink_unit: UNITS.find(
                (o) => o.value == sessionItem.ambr.downlink.unit
              ),
              session_ambr_uplink: sessionItem.ambr.uplink.value,
              session_ambr_uplink_unit: UNITS.find(
                (o) => o.value == sessionItem.ambr.uplink.unit
              ),
              ue_ipv4_address: sessionItem.ue.addr,
              ue_ipv6_address: sessionItem.ue.addr6,
              smf_ipv4_address: sessionItem.smf.addr,
              smf_ipv6_address: sessionItem.smf.addr6,
              pcc_rule: sessionItem.pcc_rule.map((ruleItem) => ({
                qi_qci: QI_QCI_DATA.find((o) => o.value == ruleItem.qos.index),
                arp_priority_level: PRIORITY_LEVEL_DATA.find(
                  (o) => o.value == ruleItem.qos.arp.priority_level
                ),
                capability: STATUS_DATA.find(
                  (o) => o.value == ruleItem.qos.arp.pre_emption_capability
                ),
                vulnerability: STATUS_DATA.find(
                  (o) => o.value == ruleItem.qos.arp.pre_emption_vulnerability
                ),
                mbr_downlink: ruleItem.qos.mbr.downlink.value,
                mbr_downlink_unit: UNITS.find(
                  (o) => o.value == ruleItem.qos.mbr.downlink.unit
                ),
                mbr_uplink: ruleItem.qos.mbr.uplink.value,
                mbr_uplink_unit: UNITS.find(
                  (o) => o.value == ruleItem.qos.mbr.uplink.unit
                ),
                gbr_downlink: ruleItem.qos.gbr.downlink.value,
                gbr_downlink_unit: UNITS.find(
                  (o) => o.value == ruleItem.qos.gbr.downlink.unit
                ),
                gbr_uplink: ruleItem.qos.gbr.uplink.value,
                gbr_uplink_unit: UNITS.find(
                  (o) => o.value == ruleItem.qos.gbr.uplink.unit
                ),
                flow: ruleItem.flow.map((flowItem) => ({
                  direction: DIRECTION_DATA.find(
                    (o) => o.value == flowItem.direction
                  ),
                  description: flowItem.description,
                  id: flowItem._id,
                })),
                id: ruleItem._id,
              })),
              id: sessionItem._id,
            })),
            id: sliceItem._id,
          })),
          id: res._id,
        };
        updateSubscriberController.setValues(newObject);
        setViewSubscriberData(res);
      } else {
        navigate("/subscribers/all");
        toast.success("Subsctiber not found!");
      }
    } catch ({ err, response }) {
      setLoadings({ ...loadings, getSubscriberById: false });
    }
  };

  const handleValidateForm = (formControllerMethod) => {
    setShowValidations(false);
    // constants
    let formData = { ...formControllerMethod.values };
    let errors = { ...validations };
    const isValidHex = (value) => /^[0-9a-fA-F\s]+$/.test(value);
    const isValidIPv4 = (value) =>
      /^((25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})\.){3}(25[0-5]|2[0-4][0-9]|1?[0-9]{1,2})$/.test(
        value
      );
    const isValidIPv6 = (value) =>
      /^(([0-9a-fA-F]{1,4}:){7,7}[0-9a-fA-F]{1,4}|([0-9a-fA-F]{1,4}:){1,7}:|([0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}|([0-9a-fA-F]{1,4}:){1,5}(:[0-9a-fA-F]{1,4}){1,2}|([0-9a-fA-F]{1,4}:){1,4}(:[0-9a-fA-F]{1,4}){1,3}|([0-9a-fA-F]{1,4}:){1,3}(:[0-9a-fA-F]{1,4}){1,4}|([0-9a-fA-F]{1,4}:){1,2}(:[0-9a-fA-F]{1,4}){1,5}|[0-9a-fA-F]{1,4}:((:[0-9a-fA-F]{1,4}){1,6})|:((:[0-9a-fA-F]{1,4}){1,7}|:)|fe80:(:[0-9a-fA-F]{0,4}){0,4}%[0-9a-zA-Z]{1,}|::(ffff(:0{1,4}){0,1}:){0,1}(([0-9]{1,3}\.){3}[0-9]{1,3})|([0-9a-fA-F]{1,4}:){1,4}:(([0-9]{1,3}\.){3}[0-9]{1,3}))$/.test(
        value
      );

    // imsi
    if (formData.imsi.length == 0) {
      errors["imsi"] = "IMSI field is require.";
    } else if (formData.imsi.length > 0 && formData.imsi.length > 15) {
      errors["imsi"] = "does not meet maximum length of 15.";
    } else {
      errors["imsi"] = "";
    }
    // msisdn
    if (formData.msisdn?.length > 0) {
      if (formData.msisdn[0]?.length == 0) {
        errors["msisdn_1"] = "MSISDN 1 field is require.";
      } else {
        errors["msisdn_1"] = "";
      }
      if (formData.msisdn[1]?.length == 0) {
        errors["msisdn_2"] = "MSISDN 2 field is require.";
      } else {
        errors["msisdn_2"] = "";
      }
    } else {
      errors["msisdn_1"] = "";
      errors["msisdn_2"] = "";
    }
    // subscriber_key
    if (formData.subscriber_key.length == 0) {
      errors["subscriber_key"] = "Subscriber Key (K) field is require.";
    } else if (!isValidHex(formData.subscriber_key)) {
      errors["subscriber_key"] = "Only hexadecimal digits are allowed.";
    } else {
      errors["subscriber_key"] = "";
    }
    // amf
    if (formData.amf.length == 0) {
      errors["amf"] = "Authentication Management Field (AMF) field is require.";
    } else if (!isValidHex(formData.amf)) {
      errors["amf"] = "Only hexadecimal digits are allowed.";
    } else {
      errors["amf"] = "";
    }
    // operator_key
    if (formData.operator_key.length == 0) {
      errors["operator_key"] = "Operator Key (OPc/OP) field is require.";
    } else if (!isValidHex(formData.operator_key)) {
      errors["operator_key"] = "Only hexadecimal digits are allowed.";
    } else {
      errors["operator_key"] = "";
    }
    // ue_ambr_downlink
    if (formData.ue_ambr_downlink.length == 0) {
      errors["ue_ambr_downlink"] = "UE-AMBR Downlink field is require.";
    } else {
      errors["ue_ambr_downlink"] = "";
    }
    // ue_ambr_uplink
    if (formData.ue_ambr_uplink.length == 0) {
      errors["ue_ambr_uplink"] = "UE-AMBR Uplink field is require.";
    } else {
      errors["ue_ambr_uplink"] = "";
    }
    // sd
    formData.slice?.map((insideSlice, index) => {
      if (insideSlice?.sd?.length > 0 && insideSlice?.sd?.length !== 6) {
        errors[`sd_${index}`] = "The length of sd should be 6.";
      } else if (insideSlice.sd.length > 0 && !isValidHex(insideSlice.sd)) {
        errors[`sd_${index}`] = "Only hexadecimal digits are allowed.";
      } else {
        errors[`sd_${index}`] = "";
      }
    });
    // session dnn_apn
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (insideSession.dnn_apn.length == 0) {
          errors[`session_dnn_apn_${sessionIndex}`] =
            "DNN/APN field is require.";
        } else {
          errors[`session_dnn_apn_${sessionIndex}`] = "";
        }
      });
    });
    // session session_ambr_downlink
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (insideSession.session_ambr_downlink.length == 0) {
          errors[`session_ambr_downlink_${sessionIndex}`] =
            "Session-AMBR Downlink field is require.";
        } else {
          errors[`session_ambr_downlink_${sessionIndex}`] = "";
        }
      });
    });
    // session session_ambr_uplink
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (insideSession.session_ambr_uplink.length == 0) {
          errors[`session_ambr_uplink_${sessionIndex}`] =
            "Session-AMBR Uplink field is require.";
        } else {
          errors[`session_ambr_uplink_${sessionIndex}`] = "";
        }
      });
    });
    // session ue_ipv4_address
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session?.map((insideSession, sessionIndex) => {
        if (
          insideSession.ue_ipv4_address?.length > 0 &&
          !isValidIPv4(insideSession.ue_ipv4_address)
        ) {
          errors[`session_ue_ipv4_address_${sessionIndex}`] =
            "does not conform to the IPv4 format.";
        } else {
          errors[`session_ue_ipv4_address_${sessionIndex}`] = "";
        }
      });
    });
    // session ue_ipv6_address
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (
          insideSession.ue_ipv6_address?.length > 0 &&
          !isValidIPv6(insideSession.ue_ipv6_address)
        ) {
          errors[`session_ue_ipv6_address_${sessionIndex}`] =
            "does not conform to the IPv6 format.";
        } else {
          errors[`session_ue_ipv6_address_${sessionIndex}`] = "";
        }
      });
    });
    // session smf_ipv4_address
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (
          insideSession.smf_ipv4_address?.length > 0 &&
          !isValidIPv4(insideSession.smf_ipv4_address)
        ) {
          errors[`session_smf_ipv4_address_${sessionIndex}`] =
            "does not conform to the IPv4 format.";
        } else {
          errors[`session_smf_ipv4_address_${sessionIndex}`] = "";
        }
      });
    });
    // session smf_ipv6_address
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (
          insideSession.smf_ipv6_address?.length > 0 &&
          !isValidIPv6(insideSession.smf_ipv6_address)
        ) {
          errors[`session_smf_ipv6_address_${sessionIndex}`] =
            "does not conform to the IPv6 format.";
        } else {
          errors[`session_smf_ipv6_address_${sessionIndex}`] = "";
        }
      });
    });
    // session rule flow description
    formData.slice?.map((insideSlice, index) => {
      insideSlice.session.map((insideSession, sessionIndex) => {
        if (insideSession.pcc_rule.length > 0) {
          insideSession.pcc_rule.map((insideRule, ruleIndex) => {
            if (insideRule.flow.length > 0) {
              insideRule.flow?.map((insideFlow, flowIndex) => {
                if (insideFlow.description.length == 0) {
                  errors[
                    `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
                  ] = "Description field is require.";
                } else if (!insideFlow.description.startsWith("permit out")) {
                  errors[
                    `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
                  ] = "Begin with reserved keyword 'permit out'.";
                } else {
                  errors[
                    `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
                  ] = "";
                }
              });
            }
          });
        }
      });
    });
    setValidations(errors);
    setShowValidations(true);
  };

  const createSubscriberController = useFormik({
    initialValues: {
      imsi: "",
      msisdn: [],
      subscriber_key: "465B5CE8 B199B49F AA5F0A2E E238A6BC",
      amf: "8000",
      usim_type: { label: "OPc", value: 0 },
      operator_key: "E8ED289D EBA952E4 283B54E8 8E6183CA",
      ue_ambr_downlink: "1",
      ue_ambr_downlink_unit: { label: "Gbps", value: 3 },
      ue_ambr_uplink: "1",
      ue_ambr_uplink_unit: { label: "Gbps", value: 3 },
      subscriber_status: { label: "SERVICE_GRANTED", value: 0 },
      operator_determined_barring: {
        label: "(0) All Packet Oriented Services Barred",
        value: 0,
      },
      slice: [
        {
          sst: 1,
          sd: "",
          default_indicator: true,
          session: [
            {
              dnn_apn: "internet",
              type: { label: "IPv4v6", value: 3 },
              qi_qci: { label: "9", value: 9 },
              arp_priority_level: { label: "8", value: 8 },
              capability: { label: "Disabled", value: 1 },
              vulnerability: { label: "Disabled", value: 1 },
              session_ambr_downlink: "1",
              session_ambr_downlink_unit: { label: "Gbps", value: 3 },
              session_ambr_uplink: "1",
              session_ambr_uplink_unit: { label: "Gbps", value: 3 },
              ue_ipv4_address: "",
              ue_ipv6_address: "",
              smf_ipv4_address: "",
              smf_ipv6_address: "",
              pcc_rule: [],
            },
          ],
        },
      ],
    },
    validationSchema: null,
    enableReinitialize: true,
    onSubmit: (values) => {
      let errors = [];
      Object.keys(validations).map((item) => {
        if (validations[item].length > 0) {
          errors.push(item);
        }
      });
      if (errors.length > 0) {
        toast.error("Please enter all data first correctly");
        window.scrollTo({
          top: 0,
          behavior: "smooth",
        });
      } else {
        createSubscriber(values);
      }
    },
  });

  const createSubscriber = async (values) => {
    let postData = {
      imsi: values.imsi,
      msisdn: values.msisdn,
      security: {
        k: values.subscriber_key,
        amf: values.amf,
        op_type: values.usim_type.value,
        op_value: values.operator_key,
        op: null,
        opc: values.operator_key,
      },
      ambr: {
        downlink: {
          value: parseFloat(values.ue_ambr_downlink),
          unit: values.ue_ambr_downlink_unit.value,
        },
        uplink: {
          value: parseFloat(values.ue_ambr_uplink),
          unit: values.ue_ambr_uplink_unit.value,
        },
      },
      slice: values.slice.map((sliceItem) => ({
        sst: parseFloat(sliceItem.sst),
        sd: sliceItem.sd,
        default_indicator: sliceItem.default_indicator,
        session: sliceItem.session.map((sessionItem) => ({
          name: sessionItem.dnn_apn,
          type: sessionItem.type.value,
          qos: {
            index: sessionItem.qi_qci.value,
            arp: {
              priority_level: sessionItem.arp_priority_level.value,
              pre_emption_capability: sessionItem.capability.value,
              pre_emption_vulnerability: sessionItem.vulnerability.value,
            },
          },
          ambr: {
            downlink: {
              value: parseFloat(sessionItem.session_ambr_downlink),
              unit: sessionItem.session_ambr_downlink_unit.value,
            },
            uplink: {
              value: parseFloat(sessionItem.session_ambr_uplink),
              unit: sessionItem.session_ambr_uplink_unit.value,
            },
          },
          ue: {
            addr: sessionItem.ue_ipv4_address,
            addr6: sessionItem.ue_ipv6_address,
          },
          smf: {
            addr: sessionItem.smf_ipv4_address,
            addr6: sessionItem.smf_ipv6_address,
          },
          pcc_rule: sessionItem.pcc_rule.map((rule_item) => ({
            qos: {
              index: rule_item.qi_qci.value,
              arp: {
                priority_level: rule_item.arp_priority_level.value,
                pre_emption_capability: rule_item.capability.value,
                pre_emption_vulnerability: rule_item.capability.value,
              },
              mbr: {
                downlink: {
                  value: parseFloat(rule_item.mbr_downlink),
                  unit: rule_item.mbr_downlink_unit.value,
                },
                uplink: {
                  value: parseFloat(rule_item.mbr_uplink),
                  unit: rule_item.mbr_uplink_unit.value,
                },
              },
              gbr: {
                downlink: {
                  value: parseFloat(rule_item.gbr_downlink),
                  unit: rule_item.gbr_downlink_unit.value,
                },
                uplink: {
                  value: parseFloat(rule_item.gbr_uplink),
                  unit: rule_item.gbr_uplink_unit.value,
                },
              },
            },
            flow: rule_item.flow.map((flowItem) => ({
              direction: flowItem.direction.value,
              description: flowItem.description,
              _id: "",
            })),
            _id: "",
          })),
          _id: "",
        })),
        _id: "",
      })),
      purge_flag: [],
      mme_host: [],
      subscriber_status: values.subscriber_status.value,
      imeisv: [],
      network_access_mode: 0,
      subscribed_rau_tau_timer: 12,
      mme_realm: [],
      __v: 0,
      access_restriction_data: 32,
      schema_version: 1,
      _id: "",
    };
    try {
      setLoadings({ ...loadings, createSubscriber: true });
      const response = await httpService.post("/v1/subscribers", postData);
      setLoadings({ ...loadings, createSubscriber: false });
      if (response.status == 201) {
        toast.success("Created successfully.");
        navigate("/subscribers/all");
      }
    } catch ({ err, response }) {
      setLoadings({ ...loadings, createSubscriber: false });
    }
  };

  const updateSubscriberController = useFormik({
    initialValues: {
      imsi: "",
      msisdn: [],
      subscriber_key: "",
      amf: "",
      usim_type: null,
      operator_key: "",
      ue_ambr_downlink: "",
      ue_ambr_downlink_unit: null,
      ue_ambr_uplink: "",
      ue_ambr_uplink_unit: null,
      subscriber_status: null,
      operator_determined_barring: null,
      slice: [],
    },
    validationSchema: null,
    enableReinitialize: true,
    onSubmit: (values) => {
      let errors = [];
      Object.keys(validations).map((item) => {
        if (validations[item].length > 0) {
          errors.push(item);
        }
      });
      if (errors.length > 0) {
        toast.error("Please enter all data first correctly");
        window.scrollTo({
          top: 0,
          behavior: "smooth",
        });
      } else {
        updateSubscriber(values);
      }
    },
  });

  const updateSubscriber = async (values) => {
    let postData = {
      imsi: values.imsi,
      msisdn: values.msisdn,
      security: {
        k: values.subscriber_key,
        amf: values.amf,
        op_type: values.usim_type.value,
        op_value: values.operator_key,
        op: null,
        opc: values.operator_key,
      },
      ambr: {
        downlink: {
          value: parseFloat(values.ue_ambr_downlink),
          unit: values.ue_ambr_downlink_unit.value,
        },
        uplink: {
          value: parseFloat(values.ue_ambr_uplink),
          unit: values.ue_ambr_uplink_unit.value,
        },
      },
      slice: values.slice.map((sliceItem) => ({
        sst: parseFloat(sliceItem.sst),
        sd: sliceItem.sd,
        default_indicator: sliceItem.default_indicator,
        session: sliceItem.session.map((sessionItem) => ({
          name: sessionItem.dnn_apn,
          type: sessionItem.type.value,
          qos: {
            index: sessionItem.qi_qci.value,
            arp: {
              priority_level: sessionItem.arp_priority_level.value,
              pre_emption_capability: sessionItem.capability.value,
              pre_emption_vulnerability: sessionItem.vulnerability.value,
            },
          },
          ambr: {
            downlink: {
              value: parseFloat(sessionItem.session_ambr_downlink),
              unit: sessionItem.session_ambr_downlink_unit.value,
            },
            uplink: {
              value: parseFloat(sessionItem.session_ambr_uplink),
              unit: sessionItem.session_ambr_uplink_unit.value,
            },
          },
          ue: {
            addr: sessionItem.ue_ipv4_address,
            addr6: sessionItem.ue_ipv6_address,
          },
          smf: {
            addr: sessionItem.smf_ipv4_address,
            addr6: sessionItem.smf_ipv6_address,
          },
          pcc_rule: sessionItem.pcc_rule.map((rule_item) => ({
            qos: {
              index: rule_item.qi_qci.value,
              arp: {
                priority_level: rule_item.arp_priority_level.value,
                pre_emption_capability: rule_item.capability.value,
                pre_emption_vulnerability: rule_item.capability.value,
              },
              mbr: {
                downlink: {
                  value: parseFloat(rule_item.mbr_downlink),
                  unit: rule_item.mbr_downlink_unit.value,
                },
                uplink: {
                  value: parseFloat(rule_item.mbr_uplink),
                  unit: rule_item.mbr_uplink_unit.value,
                },
              },
              gbr: {
                downlink: {
                  value: parseFloat(rule_item.gbr_downlink),
                  unit: rule_item.gbr_downlink_unit.value,
                },
                uplink: {
                  value: parseFloat(rule_item.gbr_uplink),
                  unit: rule_item.gbr_uplink_unit.value,
                },
              },
            },
            flow: rule_item.flow.map((flowItem) => ({
              direction: flowItem.direction.value,
              description: flowItem.description,
              _id: "",
            })),
            _id: "",
          })),
          _id: "",
        })),
        _id: "",
      })),
      purge_flag: [],
      mme_host: [],
      subscriber_status: values.subscriber_status.value,
      imeisv: [],
      network_access_mode: 0,
      subscribed_rau_tau_timer: 12,
      mme_realm: [],
      __v: 0,
      access_restriction_data: 32,
      schema_version: 1,
      _id: "",
    };
    try {
      setLoadings({ ...loadings, updateSubscriber: true });
      const response = await httpService.put(
        `/v1/subscribers/imsi/${values.imsi}`,
        postData
      );
      setLoadings({ ...loadings, updateSubscriber: false });
      if (response.status == 201) {
        toast.success("Created successfully.");
        navigate("/subscribers/all");
      }
    } catch ({ err, response }) {
      setLoadings({ ...loadings, updateSubscriber: false });
    }
  };

  const deleteSubscriber = async (imsi) => {
    try {
      setLoadings({ ...loadings, deleteSubscriber: true });
      const response = await httpService.delete(`/v1/subscribers/imsi/${imsi}`);
      setLoadings({ ...loadings, deleteSubscriber: false });
      dispatch(setDeleteModal(null));
      message.success("Subscriber deleted successfully.");
      getSubscribers(1, true);
      setPaginates({ ...paginates, current: 1 });
      setFilters({ ...filters, imsi: "" });
    } catch ({ err, response }) {
      setLoadings({ ...loadings, deleteSubscriber: false });
    }
  };

  const exports = {
    getSubscribers,
    getSubscriberById,
    deleteSubscriber,
    createSubscriberController,
    updateSubscriberController,
    handleValidateForm,
    subscribersData,
    validations,
    showValidations,
    filters,
    setFilters,
    paginates,
    setPaginates,
    loadings,
    openSearchbar,
    setOpenSearchbar,
    viewSubscriberData,
  };
  return exports;
};
export default useSubscribers;
