export default class formatHelper {
  static generateRandomHex() {
    let length = 24;
    const characters = "0123456789abcdef";
    let result = "";

    for (let i = 0; i < length; i++) {
      const randomIndex = Math.floor(Math.random() * characters.length);
      result += characters[randomIndex];
    }

    return result;
  }
  static numberSeperator(number) {
    if (typeof number === "string") {
      return number?.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    } else {
      return number?.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    }
  }
  static priceFormatter(number) {
    if (typeof number === "string") {
      return parseFloat(number).toFixed(5);
    } else {
      return number.toFixed(5);
    }
  }
  static toEnglishString(str) {
    if (str) {
      if (typeof str === "string") {
        return str
          .replace(/۱/g, "1")
          .replace(/۲/g, "2")
          .replace(/۳/g, "3")
          .replace(/۴/g, "4")
          .replace(/۵/g, "5")
          .replace(/۶/g, "6")
          .replace(/۷/g, "7")
          .replace(/۸/g, "8")
          .replace(/۹/g, "9")
          .replace(/۰/g, "0");
      } else {
        return str
          .toString()
          .replace(/۱/g, "1")
          .toString()
          .replace(/۲/g, "2")
          .toString()
          .replace(/۳/g, "3")
          .toString()
          .replace(/۴/g, "4")
          .toString()
          .replace(/۵/g, "5")
          .toString()
          .replace(/۶/g, "6")
          .toString()
          .replace(/۷/g, "7")
          .toString()
          .replace(/۸/g, "8")
          .toString()
          .replace(/۹/g, "9")
          .toString()
          .replace(/۰/g, "0");
      }
    } else {
      return "";
    }
  }
}
